import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

exclusive_cumsum_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <stdio.h>

// A simple kernel that computes the exclusive cumsum along dim=1 for a 2D tensor.
// For each row, it does a sequential scan on the GPU with one thread per row.
__global__ void exclusive_cumsum_kernel_dim1(const float* __restrict__ input,
                                             float* __restrict__ output,
                                             const int rows,
                                             const int cols) {
    int row = blockIdx.x;
    if (row >= rows) return;

    // Only one thread per row:
    float running_sum = 0.0f;
    for (int i = 0; i < cols; i++) {
        output[row * cols + i] = running_sum;
        running_sum += input[row * cols + i];
    }
}

// A wrapper function that handles the forward pass and dispatches the kernel for dim=1.
// If you wanted to handle other dims or more complicated shapes, you'd add logic here.
torch::Tensor exclusive_cumsum_cuda(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.dim() == 2, "This example kernel only supports 2D tensors.");
    TORCH_CHECK(dim == 1, "This example kernel only supports cumsum along dim=1.");

    // Prepare output
    auto output = torch::zeros_like(x);

    // Get shapes
    int rows = x.size(0);
    int cols = x.size(1);

    // Launch one block per row, with 1 thread per block
    dim3 grid(rows), block(1);

    // Run kernel
    exclusive_cumsum_kernel_dim1<<<grid, block>>>(x.data_ptr<float>(),
                                                  output.data_ptr<float>(),
                                                  rows,
                                                  cols);
    return output;
}
"""

exclusive_cumsum_cpp_source = r"torch::Tensor exclusive_cumsum_cuda(torch::Tensor x, int64_t dim);"

# Build the inline extension
exclusive_cumsum = load_inline(
    name="exclusive_cumsum",
    cpp_sources=exclusive_cumsum_cpp_source,
    cuda_sources=exclusive_cumsum_source,
    functions=["exclusive_cumsum_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, dim):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.exclusive_cumsum = exclusive_cumsum

    def forward(self, x):
        return self.exclusive_cumsum.exclusive_cumsum_cuda(x, self.dim)
